import{_ as p,a0 as o,w as d,s as r,I as t,a1 as e,A as n,x as a,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Debian 10（Buster）安装后要做的前 8 件事 | LCTT x X-CMD","titleTemplate":false,"description":"Debian 10（Buster）安装后要做的前 8 件事 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Debian 10（Buster）安装后要做的前 8 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Debian 10（Buster）安装后要做的前 8 件事 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190729 Top 8 Things to do after Installing Debian 10 (Buster)","title":"Debian 10（Buster）安装后要做的前 8 件事","tag":"201908","desc":""},"relativePath":"201908/20190729 Top 8 Things to do after Installing Debian 10 (Buster).md","filePath":"[post].md"}'),h={name:"201908/20190729 Top 8 Things to do after Installing Debian 10 (Buster).md"};function u(g,s,c,b,k,f){const i=o("Link");return d(),r("div",null,[t("p",null,[e(i,{href:"collector:",title:"lujun9972"},{default:n(()=>[...s[0]||(s[0]=[a("#",-1)])]),_:1}),s[5]||(s[5]=a(": subject: (Top 8 Things to do after Installing Debian 10 (Buster)) ",-1)),e(i,{href:"collector:",title:"lujun9972"},{default:n(()=>[...s[1]||(s[1]=[a("#",-1)])]),_:1}),s[6]||(s[6]=a(": via: (",-1)),e(i,{href:"https://www.linuxtechi.com/things-to-do-after-installing-debian-10/"},{default:n(()=>[...s[2]||(s[2]=[a("https://www.linuxtechi.com/things-to-do-after-installing-debian-10/",-1)])]),_:1}),s[7]||(s[7]=a(") ",-1)),e(i,{href:"collector:",title:"lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("#",-1)])]),_:1}),s[8]||(s[8]=a(": author: (Pradeep Kumar ",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[4]||(s[4]=[a("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),s[9]||(s[9]=a(")",-1))]),s[31]||(s[31]=t("h1",{id:"debian-10-buster-安装后要做的前-8-件事",tabindex:"-1"},[a("Debian 10（Buster）安装后要做的前 8 件事 "),t("a",{class:"header-anchor",href:"#debian-10-buster-安装后要做的前-8-件事","aria-label":"Permalink to “Debian 10（Buster）安装后要做的前 8 件事”"},"​")],-1)),t("p",null,[s[11]||(s[11]=a("Debian 10 的代号是 Buster，它是来自 Debian 家族的最新 LTS 发布版本，并包含大量的特色功能。因此，如果你已经在你的电脑上安装了 Debian 10，并在思考接下来该做什么，那么，请继续阅读这篇文章直到结尾，因为我们为你提供在安装 Debian 10 后要做的前 8 件事。对于还没有安装 Debian 10 的人们，请阅读这篇指南 ",-1)),e(i,{href:"https://linux.cn/article-11083-1.html"},{default:n(()=>[...s[10]||(s[10]=[a("图解 Debian 10 (Buster) 安装步骤",-1)])]),_:1}),s[12]||(s[12]=a("。 让我们继续这篇文章。",-1))]),s[32]||(s[32]=l(`<p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Things-to-do-after-installing-debian10.jpg" alt=""></p><h3 id="_1-安装和配置-sudo" tabindex="-1">1) 安装和配置 sudo <a class="header-anchor" href="#_1-安装和配置-sudo" aria-label="Permalink to “1) 安装和配置 sudo”">​</a></h3><p>在设置完成 Debian 10 后，你需要做的第一件事是安装 sudo 软件包，因为它能够使你获得管理员权限来安装你需要的软件包。为安装和配置 sudo，请使用下面的命令：</p><p>变成 root 用户，然后使用下面的命令安装 sudo 软件包，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ su -</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>root@linuxtechi:~# apt install sudo -y</span></span></code></pre></div>`,5)),t("p",null,[s[14]||(s[14]=a("添加你的本地用户到 sudo 组，使用下面的 ",-1)),e(i,{href:"https://www.linuxtechi.com/linux-commands-to-manage-local-accounts/"},{default:n(()=>[...s[13]||(s[13]=[a("usermod",-1)])]),_:1}),s[15]||(s[15]=a(" 命令，",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~# usermod -aG sudo pkumar</span></span>
<span class="line"><span>root@linuxtechi:~#</span></span></code></pre></div><p>现在验证是否本地用户获得 sudo 权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ id</span></span>
<span class="line"><span>uid=1000(pkumar) gid=1000(pkumar) groups=1000(pkumar),27(sudo)</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo vi /etc/hosts</span></span>
<span class="line"><span>[sudo] password for pkumar:</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><h3 id="_2-校正日期和时间" tabindex="-1">2) 校正日期和时间 <a class="header-anchor" href="#_2-校正日期和时间" aria-label="Permalink to “2) 校正日期和时间”">​</a></h3><p>在你成功配置 sudo 软件包后，接下来，你需要根据你的位置来校正日期和时间。为了校正日期和时间，</p><p>转到系统 <strong>设置</strong> –&gt; <strong>详细说明</strong> –&gt; <strong>日期和时间</strong> ，然后更改为适合你的位置的时区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Adjust-date-time-Debian10.jpg" alt=""></p><p>一旦时区被更改，你可以看到时钟中的时间自动更改。</p><h3 id="_3-应用所有更新" tabindex="-1">3) 应用所有更新 <a class="header-anchor" href="#_3-应用所有更新" aria-label="Permalink to “3) 应用所有更新”">​</a></h3><p>在 Debian 10 安装后，建议安装所有 Debian 10 软件包存储库中可用的更新，执行下面的 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt upgrade -y</span></span></code></pre></div><p><strong>注意：</strong> 如果你是 vi 编辑器的忠实粉丝，那么使用下面的 <code>apt</code> 命令安装 <code>vim</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install vim -y</span></span></code></pre></div><h3 id="_4-安装-flash-播放器插件" tabindex="-1">4) 安装 Flash 播放器插件 <a class="header-anchor" href="#_4-安装-flash-播放器插件" aria-label="Permalink to “4) 安装 Flash 播放器插件”">​</a></h3><p>默认情况下，Debian 10（Buster）存储库不包含 Flash 插件，因此，用户需要遵循下面的介绍来在他们的系统中查找和安装 flash 播放器。</p><p>为 Flash 播放器配置存储库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ echo &quot;deb http://ftp.de.debian.org/debian buster main contrib&quot; | sudo tee -a  /etc/apt/sources.list</span></span>
<span class="line"><span>deb http://ftp.de.debian.org/debian buster main contrib</span></span>
<span class="line"><span>root@linuxtechi:~</span></span></code></pre></div><p>现在使用下面的命令更新软件包索引：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span></code></pre></div><p>使用下面的 <code>apt</code> 命令安装 Flash 插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install pepperflashplugin-nonfree -y</span></span></code></pre></div><p>一旦软件包被成功安装，接下来，尝试播放 YouTube 中的视频：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Flash-Player-plugin-Debian10.jpg" alt=""></p><h3 id="_5-安装软件-如-vlc、skype、filezilla-和截图工具" tabindex="-1">5) 安装软件，如 VLC、Skype、FileZilla 和截图工具 <a class="header-anchor" href="#_5-安装软件-如-vlc、skype、filezilla-和截图工具" aria-label="Permalink to “5) 安装软件，如 VLC、Skype、FileZilla 和截图工具”">​</a></h3><p>如此，现在我们已经启用 Flash 播放器，是时候在我们的 Debian 10 系统中安装所有其它的软件，如 VLC、Skype，Filezilla 和截图工具（flameshot）。</p><h4 id="安装-vlc-多媒体播放器" tabindex="-1">安装 VLC 多媒体播放器 <a class="header-anchor" href="#安装-vlc-多媒体播放器" aria-label="Permalink to “安装 VLC 多媒体播放器”">​</a></h4><p>为在你的系统中安装 VLC 播放器，使用下面的 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install vlc -y</span></span></code></pre></div><p>在成功安装 VLC 播放器后，尝试播放你喜欢的视频。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Debian10-VLC.jpg" alt=""></p><h4 id="安装-skype" tabindex="-1">安装 Skype <a class="header-anchor" href="#安装-skype" aria-label="Permalink to “安装 Skype”">​</a></h4><p>首先，下载最新的 Skype 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ wget https://go.skype.com/skypeforlinux-64.deb</span></span></code></pre></div><p>接下来，使用 <code>apt</code> 命令安装软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install ./skypeforlinux-64.deb</span></span></code></pre></div><p>在成功安装 Skype 后，尝试访问它，并输入你的用户名和密码。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/skype-Debian10.jpg" alt=""></p><h4 id="安装-filezilla" tabindex="-1">安装 Filezilla <a class="header-anchor" href="#安装-filezilla" aria-label="Permalink to “安装 Filezilla”">​</a></h4><p>为在你的系统中安装 Filezilla，使用下面的 <code>apt</code> 命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install filezilla -y</span></span></code></pre></div><p>一旦 FileZilla 软件包被成功安装，尝试访问它。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/FileZilla-Debian10.jpg" alt=""></p><h4 id="安装截图工具-flameshot" tabindex="-1">安装截图工具（flameshot） <a class="header-anchor" href="#安装截图工具-flameshot" aria-label="Permalink to “安装截图工具（flameshot）”">​</a></h4><p>使用下面的命令来安装截图工具：flameshot，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install flameshot -y</span></span></code></pre></div><p><strong>注意：</strong> Shutter 工具在 Debian 10 中已被移除。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/flameshoot-debian10.jpg" alt=""></p><h3 id="_6-启用和启动防火墙" tabindex="-1">6) 启用和启动防火墙 <a class="header-anchor" href="#_6-启用和启动防火墙" aria-label="Permalink to “6) 启用和启动防火墙”">​</a></h3><p>总是建议启动防火墙来使你的网络安全。如果你希望在 Debian 10 中启用防火墙， <strong>UFW</strong>（简单的防火墙）是最好的控制防火墙的工具。UFW 在 Debian 存储库中可用，它非常容易安装，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt install ufw</span></span></code></pre></div><p>在你安装 UFW 后，接下来的步骤是设置防火墙。因此，设置防火墙，通过拒绝端口来禁用所有的传入流量，并且只允许需要的端口传出，像 ssh、http 和 https。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw default deny incoming</span></span>
<span class="line"><span>Default incoming policy changed to &#39;deny&#39;</span></span>
<span class="line"><span>(be sure to update your rules accordingly)</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ufw default allow outgoing</span></span>
<span class="line"><span>Default outgoing policy changed to &#39;allow&#39;</span></span>
<span class="line"><span>(be sure to update your rules accordingly)</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>允许 SSH 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw allow ssh</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>假使你在系统中已经安装 Web 服务器，那么使用下面的 <code>ufw</code> 命令来在防火墙中允许它们的端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw allow 80</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo ufw allow 443</span></span>
<span class="line"><span>Rules updated</span></span>
<span class="line"><span>Rules updated (v6)</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>最后，你可以使用下面的命令启用 UFW：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw enable</span></span>
<span class="line"><span>Command may disrupt existing ssh connections. Proceed with operation (y|n)? y</span></span>
<span class="line"><span>Firewall is active and enabled on system startup</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>假使你想检查你的防火墙的状态，你可以使用下面的命令检查它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo ufw status</span></span></code></pre></div><h3 id="_7-安装虚拟化软件-virtualbox" tabindex="-1">7) 安装虚拟化软件（VirtualBox） <a class="header-anchor" href="#_7-安装虚拟化软件-virtualbox" aria-label="Permalink to “7) 安装虚拟化软件（VirtualBox）”">​</a></h3><p>安装 Virtualbox 的第一步是将 Oracle VirtualBox 存储库的公钥导入到你的 Debian 10 系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ wget -q https://www.virtualbox.org/download/oracle_vbox_2016.asc -O- | sudo apt-key add -</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>root@linuxtechi:~$ wget -q https://www.virtualbox.org/download/oracle_vbox.asc -O- | sudo apt-key add -</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>如果导入成功，你将看到一个 “OK” 显示信息。</p><p>接下来，你需要添加存储库到仓库列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo add-apt-repository &quot;deb http://download.virtualbox.org/virtualbox/debian buster contrib&quot;</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>最后，是时候在你的系统中安装 VirtualBox 6.0：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt install virtualbox-6.0 -y</span></span></code></pre></div><p>一旦 VirtualBox 软件包被成功安装，尝试访问它，并开始创建虚拟机。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/VirtualBox6-Debian10-Workstation.jpg" alt=""></p><h3 id="_8-安装最新的-amd-驱动程序" tabindex="-1">8) 安装最新的 AMD 驱动程序 <a class="header-anchor" href="#_8-安装最新的-amd-驱动程序" aria-label="Permalink to “8) 安装最新的 AMD 驱动程序”">​</a></h3><p>最后，你也可以安装需要的附加 AMD 显卡驱动程序（如 ATI 专有驱动）和 Nvidia 图形驱动程序。为安装最新的 AMD 驱动程序，首先，我们需要修改 <code>/etc/apt/sources.list</code> 文件，在包含 <strong>main</strong> 和 <strong>contrib</strong> 的行中添加 <strong>non-free</strong> 单词，示例如下显示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo vi /etc/apt/sources.list</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>...</span></span>
<span class="line"><span>deb http://deb.debian.org/debian/ buster main non-free contrib</span></span>
<span class="line"><span>deb-src http://deb.debian.org/debian/ buster main non-free contrib</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deb http://security.debian.org/debian-security buster/updates main contrib non-free</span></span>
<span class="line"><span>deb-src http://security.debian.org/debian-security buster/updates main contrib non-free</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deb http://ftp.us.debian.org/debian/ buster-updates main contrib non-free</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>现在，使用下面的 <code>apt</code> 命令来在 Debian 10 系统中安装最新的 AMD 驱动程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo apt update</span></span>
<span class="line"><span>root@linuxtechi:~$ sudo apt install firmware-linux firmware-linux-nonfree libdrm-amdgpu1 xserver-xorg-video-amdgpu -y</span></span></code></pre></div><p>这就是这篇文章的全部内容，我希望你了解在安装 Debian 10 后应该做什么。请在下面的评论区，分享你的反馈和评论。</p><hr>`,78)),t("p",null,[s[17]||(s[17]=a("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/things-to-do-after-installing-debian-10/"},{default:n(()=>[...s[16]||(s[16]=[a("https://www.linuxtechi.com/things-to-do-after-installing-debian-10/",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=a("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...s[18]||(s[18]=[a("Pradeep Kumar",-1)])]),_:1}),s[23]||(s[23]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 译者：",-1)),e(i,{href:"https://github.com/robsean"},{default:n(()=>[...s[20]||(s[20]=[a("robsean",-1)])]),_:1}),s[25]||(s[25]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[28]||(s[28]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[27]||(s[27]=[a("Linux中国",-1)])]),_:1}),s[30]||(s[30]=a(" 荣誉推出",-1))])])}const w=p(h,[["render",u]]);export{y as __pageData,w as default};
